-- Generated by tools/bundle.lua from src/. Do not edit.
local uz = uz or fb  -- Uzume < 0.22 only has the old name fb
local __mod = {}
local __loaded = {}
local function require(name)
  local m = __loaded[name]
  if m ~= nil then
    if m == __loaded then return nil end
    return m
  end
  local f = __mod[name]
  if not f then return nil end
  __loaded[name] = __loaded -- cycle guard
  local r = f(name)
  if r == nil then r = true end
  __loaded[name] = r
  return r
end
__mod["app.editor"] = function(...)
-- Controller of the Creature Editor: reads through the `pokemon.core` interface, keeps the panel state,
-- turns "Apply" into encode_pokemon / encode_money calls and writes the returned operations with
-- uz.memory.write (permission memory.write; consent, the save snapshot and the run rules belong to the app).
-- After a write the creature is read back and compared before the editor says "applied".
local form_mod = require("model.form")
local panel = require("ui.panel")

local M = {}

M.CORE_ID = "uzume.soullink-core"
M.CHECK_EVERY = 5   -- ticks between read-back attempts
M.CHECK_MAX = 12    -- attempts before "not confirmed"
M.RETRY_EVERY = 30  -- ticks between retries of the core and the name lists
M.REFRESH_EVERY = 90

local NAME_KINDS = { "species", "move", "item" }

function M.start(uz)
  local function tr(key, vars) return uz.i18n.t(key, vars) end

  local S = {
    view = "list", tab = "team", box = 1, pouch = "items", bag_filter = "", count = "", add = { filter = "", count = "1", id = "" }, filters = { species = "", move = "", item = "" }, money = "", errors = {},
  }
  local core = { state = "wait", features = {}, limits = form_mod.limits_of(nil) }
  local names = { species = nil, move = nil, item = nil, nature = {} }
  local team, box, trainer, box_count = {}, {}, nil, 31
  local bag, bag_err = nil, nil
  local ticks = 0
  local bag_enabled

  local self = { state = S, core = core, names = names }

  -- ---- core access ----

  -- uz.call into pokemon.core; returns the results, or nil, "call_failed" when the call itself raised.
  local function call(fn, ...)
    local res = table.pack(pcall(uz.call, "pokemon.core", fn, ...))
    if not res[1] then return nil, "call_failed" end
    return res[2], res[3]
  end

  local function can_write()
    return type(uz.memory) == "table" and type(uz.memory.write) == "function"
  end

  local function load_names()
    local missing = false
    for _, kind in ipairs(NAME_KINDS) do
      if not names[kind] then
        local l = call("names_list", kind)
        if type(l) == "table" and #l > 0 then names[kind] = l else missing = true end
      end
    end
    local count = 0
    for _ in pairs(names.nature) do count = count + 1 end
    if count <= core.limits.nature then
      for n = 0, core.limits.nature do
        if not names.nature[n] then
          local nm = call("name", "nature", n)
          if type(nm) == "string" and nm ~= "" then names.nature[n] = nm else missing = true end
        end
      end
    end
    names.ready = not missing
  end

  -- The item editor needs the core's bag() and encode_item() (soullink-core 0.7.0); older cores keep money only.
  function bag_enabled()
    return core.features.edit_items == true and core.features.bag == true
  end

  local function refresh_data()
    team = call("team") or {}
    if S.tab == "box" or S.view == "edit" then box = call("box", S.box) or {} end
    local n = call("box_count")
    if math.type(n) == "integer" and n >= 1 then box_count = n end
    trainer = call("trainer")
    if S.tab == "bag" and bag_enabled() then bag, bag_err = call("bag") end
  end

  local function init()
    local info = call("info")
    if type(info) ~= "table" then core.state = "no_core"; return end
    core.features = info.features or {}
    if not info.supported or not core.features.edit_pokemon then core.state = "unsupported"; return end
    if not can_write() then core.state = "no_write"; return end
    local lim = call("edit_limits")
    if type(lim) == "table" then core.limits = form_mod.limits_of(lim) end
    core.state = "ready"
    load_names()
    refresh_data()
  end

  -- ---- rendering ----

  local function render()
    local ok, tree = pcall(panel.build, {
      tr = tr, state = S, core = core, names = names, bag = bag, bag_err = bag_err, bag_on = bag_enabled(),
      team = team, box = box, box_count = box_count, trainer = trainer,
    })
    if not ok then uz.log.error("panel build failed: " .. tostring(tree)); return end
    local set_ok, err = pcall(uz.ui.set, "panel", tree)
    if not set_ok then uz.log.error("ui.set failed: " .. tostring(err)) end
  end
  self.render = render

  local function say(tone, text) S.msg = { tone = tone, text = text } end

  -- ---- writing ----

  local WRITE_MSG = { consent_required = "msg_consent", blocked_by_run_rule = "msg_blocked", unmapped = "msg_unmapped" }

  local function write_error(reason, partial)
    local key = WRITE_MSG[reason]
    local text
    if key then
      text = tr(key)
    elseif reason == "permission" then
      text = tr("msg_no_permission")
    else
      local code = type(reason) == "string" and reason:gsub("[^%w_ ]", ""):sub(1, 40) or "unknown"
      text = tr("msg_write_failed", { code = code })
    end
    if partial then text = text .. " " .. tr("msg_partial") end
    return text
  end

  -- Writes every op in order. Returns true, or false + message.
  local function write_ops(ops)
    for i, op in ipairs(ops) do
      local res = table.pack(pcall(uz.memory.write, op.addr, op.bytes))
      if not res[1] then return false, write_error("permission", i > 1) end
      if res[2] ~= true then return false, write_error(res[3], i > 1) end
    end
    return true
  end

  local CORE_ERR = { not_ready = "err_core_not_ready", empty_slot = "err_empty_slot", growth_unavailable = "err_growth",
    ev_total = "err_ev_total", invalid_location = "err_empty_slot", unsupported = "err_unsupported",
    invalid_money = "err_money", pouch_full = "err_pouch_full", invalid_slot = "err_item_changed",
    unknown_pouch = "err_unsupported" }

  local function core_error(why)
    local key = CORE_ERR[why]
    if key then return tr(key) end
    if type(why) == "string" and why:match("^invalid_") then return tr("err_invalid_field", { field = why:sub(9) }) end
    return tr("err_core", { code = type(why) == "string" and why:gsub("[^%w_:]", ""):sub(1, 40) or "unknown" })
  end

  local WARN = { pp_unknown = "warn_pp", ability_unchanged = "warn_ability", stats_stale = "warn_stats",
    exp_unchanged = "warn_exp" }

  local function warning_text(warnings)
    local out = {}
    for _, w in ipairs(warnings or {}) do
      if WARN[w] then out[#out + 1] = tr(WARN[w]) end
    end
    return table.concat(out, " ")
  end

  local function find_slot(list, slot)
    for _, r in ipairs(list or {}) do if r.slot == slot then return r end end
    return nil
  end

  local function current_record(target)
    if target.kind == "team" then return find_slot(call("team"), target.slot) end
    return find_slot(call("box", target.box), target.slot)
  end

  local function finish_pending(ok)
    local p = S.pending
    S.pending = nil
    if p.kind == "pokemon" then
      if ok then
        local rec = current_record(p.target)
        if rec and S.target and S.target.kind == p.target.kind and S.target.slot == p.target.slot
          and S.target.box == p.target.box then
          S.rec, S.form, S.errors = rec, form_mod.from_record(rec), {}
        end
        say("ok", (tr("msg_applied") .. " " .. warning_text(p.warnings)):gsub("%s+$", ""))
      else
        say("warning", tr("msg_unconfirmed"))
      end
    elseif p.kind == "item" then
      if ok then
        say("ok", tr(p.count == 0 and "msg_item_removed" or "msg_item_applied", { name = p.name }))
        S.sel = nil
      else
        say("warning", tr("msg_unconfirmed"))
      end
    else
      if ok then say("ok", tr("msg_money_applied", { n = p.value })) else say("warning", tr("msg_unconfirmed")) end
    end
    refresh_data()
    render()
  end

  local function check_pending()
    local p = S.pending
    p.tries = p.tries + 1
    local ok = false
    if p.kind == "pokemon" then
      local rec = current_record(p.target)
      ok = rec ~= nil and form_mod.matches(p.fields, rec)
    elseif p.kind == "item" then
      local b = call("bag")
      local rows = type(b) == "table" and b[p.pouch] or nil
      if rows then
        local n, hit = 0, false
        for _, r in ipairs(rows) do
          if r.item == p.item then n = n + 1; if r.count == p.count then hit = true end end
        end
        ok = p.count == 0 and n < p.before or (p.count ~= 0 and hit)
      end
    else
      local t = call("trainer")
      ok = type(t) == "table" and t.money == p.value
    end
    if ok or p.tries >= M.CHECK_MAX then finish_pending(ok) end
  end

  -- ---- actions ----

  local H = {}

  function H.tab(v)
    if v ~= "team" and v ~= "box" and v ~= "bag" then return end
    S.tab, S.msg = v, nil
    refresh_data()
  end

  function H.box_select(v)
    if math.type(v) ~= "integer" or v < 1 or v > box_count then return end
    S.box = v
    box = call("box", v) or {}
  end

  function H.edit(v)
    if type(v) ~= "table" then return end
    local rec
    if v.kind == "team" then
      team = call("team") or team
      rec = find_slot(team, v.slot)
    elseif v.kind == "box" then
      box = call("box", v.box) or box
      rec = find_slot(box, v.slot)
    end
    if not rec then
      say("warning", tr("err_empty_slot"))
      return
    end
    S.target = { kind = v.kind, slot = v.slot, box = v.box }
    S.rec, S.form, S.errors, S.msg = rec, form_mod.from_record(rec), {}, nil
    S.filters = { species = "", move = "", item = "" }
    S.view = "edit"
  end

  function H.back() S.view, S.form, S.msg, S.pending = "list", nil, nil, nil; refresh_data() end
  function H.dismiss() S.msg = nil end
  function H.reset() if S.rec then S.form, S.errors, S.msg = form_mod.from_record(S.rec), {}, nil end end

  local function revalidate()
    local _, errs = form_mod.to_fields(S.form, S.rec, core.limits)
    S.errors = errs
  end

  function H.species(v) S.form.species = v; revalidate() end
  function H.species_filter(v) S.filters.species = tostring(v or "") end
  function H.move_filter(v) S.filters.move = tostring(v or "") end
  function H.item_filter(v) S.filters.item = tostring(v or "") end
  function H.level(v) S.form.level = tostring(v or ""); revalidate() end
  function H.nature(v) S.form.nature = v; revalidate() end
  function H.shiny(v) S.form.shiny = v == true; revalidate() end
  function H.item(v) S.form.item = v; revalidate() end

  function H.apply()
    if not S.form or S.pending then return end
    local fields, errs = form_mod.to_fields(S.form, S.rec, core.limits)
    S.errors = errs
    if next(errs) then say("warning", tr("msg_fix_fields")); return end
    if next(fields) == nil then say("info", tr("msg_nothing")); return end
    local target = { kind = S.target.kind, slot = S.target.slot, box = S.target.box }
    local loc = target.kind == "team" and { kind = "team", slot = target.slot }
      or { kind = "box", box = target.box, slot = target.slot }
    local res, why = call("encode_pokemon", loc, fields)
    if not res then say("danger", core_error(why)); return end
    local ok, text = write_ops(res.ops or { { addr = res.addr, bytes = res.bytes } })
    if not ok then say("danger", text); return end
    S.pending = { kind = "pokemon", target = target, fields = fields, tries = 0, warnings = res.warnings }
    say("info", tr("msg_sent"))
  end

  function H.money_input(v) S.money, S.money_err = tostring(v or ""), nil end

  function H.money_apply()
    if S.pending then return end
    local n = form_mod.parse_int(S.money)
    if n == nil or n > core.limits.money then S.money_err = "err_money"; return end
    local res, why = call("encode_money", n)
    if not res then say("danger", core_error(why)); return end
    local ok, text = write_ops(res.ops or { { addr = res.addr, bytes = res.bytes } })
    if not ok then say("danger", text); return end
    S.pending = { kind = "money", value = n, tries = 0 }
    say("info", tr("msg_sent"))
  end

  -- ---- bag ----

  local function pouch_rows(pouch)
    return type(bag) == "table" and type(bag[pouch]) == "table" and bag[pouch] or {}
  end

  local function item_label(rows_or_nil, id)
    for _, r in ipairs(rows_or_nil or {}) do
      if r.item == id and r.name and r.name ~= "" then return r.name end
    end
    for _, e in ipairs(names.item or {}) do
      if e.id == id and e.name ~= "" then return e.name end
    end
    return "#" .. tostring(id)
  end

  -- Encodes one item change and writes all its ops in one step (removal shifts later slots, so several ops).
  local function queue_item(pouch, item, count, slot)
    local res, why = call("encode_item", pouch, item, count, slot)
    if not res then say("danger", core_error(why)); return end
    local ops = res.ops or { { addr = res.addr, bytes = res.bytes } }
    local ok, text = write_ops(ops)
    if not ok then say("danger", text); return end
    local before = 0
    for _, r in ipairs(pouch_rows(pouch)) do if r.item == item then before = before + 1 end end
    S.pending = { kind = "item", pouch = pouch, item = item, count = count, before = before, tries = 0,
      name = item_label(pouch_rows(pouch), item) }
    say("info", tr("msg_sent"))
  end

  local function parse_count(text, pouch)
    local n = form_mod.parse_int(text)
    if n == nil or n < 1 or n > form_mod.pouch_max(core.limits, pouch) then return nil end
    return n
  end

  for _, name in ipairs(form_mod.POUCHES) do
    H["pouch_" .. name] = function()
      S.pouch, S.sel, S.count_err, S.bag_filter, S.msg = name, nil, nil, "", nil
      refresh_data()
    end
  end

  function H.bag_filter(v) S.bag_filter = tostring(v or "") end

  function H.bag_edit(v)
    if type(v) ~= "table" then return end
    local row
    for _, r in ipairs(pouch_rows(S.pouch)) do if r.slot == v.slot then row = r end end
    if not row then say("warning", tr("err_item_changed")); return end
    S.sel = { pouch = S.pouch, slot = row.slot, item = row.item }
    S.count, S.count_err, S.msg = tostring(row.count), nil, nil
  end

  function H.bag_close() S.sel, S.count_err = nil, nil end
  function H.count_input(v) S.count, S.count_err = tostring(v or ""), nil end

  function H.count_apply()
    if S.pending or not S.sel then return end
    local n = parse_count(S.count, S.sel.pouch)
    if not n then S.count_err = "err_count"; return end
    queue_item(S.sel.pouch, S.sel.item, n, S.sel.slot)
  end

  function H.item_remove()
    if S.pending or not S.sel then return end
    queue_item(S.sel.pouch, S.sel.item, 0, S.sel.slot)
  end

  function H.add_filter(v) S.add.filter, S.add.item = tostring(v or ""), nil end
  function H.add_item(v) S.add.item = v end
  function H.add_id(v) S.add.id, S.add.id_err = tostring(v or ""), nil end
  function H.add_count(v) S.add.count, S.add.count_err = tostring(v or ""), nil end

  function H.add_apply()
    if S.pending then return end
    local item
    if names.item then
      item = S.add.item
      if item == nil then
        local opts = form_mod.filter_options(names.item, S.add.filter, nil, 100, function(id) return "#" .. id end)
        item = opts[1] and opts[1].value
      end
    else
      item = form_mod.parse_int(S.add.id)
    end
    if item == nil or item < 1 or item > core.limits.item then S.add.id_err = "err_item"; return end
    local n = parse_count(S.add.count, S.pouch)
    if not n then S.add.count_err = "err_count"; return end
    queue_item(S.pouch, item, n)
  end

  local function on_action(action, value)
    local handler = H[action]
    if handler then
      handler(value)
    else
      local kind, stat = action:match("^(%a+)_(%a+)$")
      if kind == "iv" or kind == "ev" then
        if S.form then
          S.form[kind == "iv" and "ivs" or "evs"][stat] = tostring(value or "")
          revalidate()
        end
      elseif action:match("^move_%d$") and S.form then
        local i = tonumber(action:sub(6))
        if i >= 1 and i <= form_mod.MOVE_SLOTS then S.form.moves[i] = value; revalidate() end
      end
    end
    render()
  end

  -- ---- start ----

  uz.ui.on_action(function(action, value, slot)
    if slot ~= "panel" then return end
    local ok, err = pcall(on_action, action, value)
    if not ok then
      uz.log.error("action " .. tostring(action) .. " failed: " .. tostring(err))
      say("danger", tr("err_internal"))
      render()
    end
  end)

  uz.on_tick(function()
    ticks = ticks + 1
    if S.pending and ticks % M.CHECK_EVERY == 0 then check_pending() end
    if ticks % M.RETRY_EVERY == 0 then
      if core.state ~= "ready" then
        init()
        render()
      elseif not names.ready then
        load_names()
        if names.ready then render() end
      end
    end
    if core.state == "ready" and S.view == "list" and not S.pending and ticks % M.REFRESH_EVERY == 0 then
      refresh_data()
      render()
    end
  end)

  pcall(uz.events.on, M.CORE_ID, "team.changed", function()
    if core.state == "ready" and S.view == "list" and not S.pending then
      refresh_data()
      render()
    end
  end)

  uz.log.info(tr("loaded", { version = uz.plugin.version }))
  init()
  render()
  return self
end

return M

end
__mod["main"] = function(...)
-- Entry module of the Creature Editor plugin.
require("app.editor").start(uz)

end
__mod["model.form"] = function(...)
-- Edit form of one creature: record -> form values (strings as typed), form -> changed fields for
-- pokemon.core `encode_pokemon`, and the checks that run before anything is encoded.
-- Pure: no uz access.
local M = {}

M.STATS = { "hp", "atk", "def", "spe", "spa", "spd" }
M.MOVE_SLOTS = 4

-- Limits used when the core does not report any (older core): the Gen 6 values.
M.DEFAULT_LIMITS = { species = 721, move = 617, item = 775, level = 100, iv = 31, ev = 255, ev_total = 510, nature = 24,
  money = 999999, item_count = 999 }

-- Bag pouches in display order (names as the core reports them).
M.POUCHES = { "items", "medicine", "berries", "tms", "key_items" }

--- Largest count a pouch takes: the core's per-pouch limit, else the general item count limit.
function M.pouch_max(limits, pouch)
  local p = type(limits.pouches) == "table" and limits.pouches[pouch] or nil
  return (p and p.max_count) or limits.item_count or 999
end

--- Pouches to offer: the ones the core lists in edit_limits (display order), else all known.
function M.pouches_of(limits)
  if type(limits.pouches) ~= "table" or next(limits.pouches) == nil then return M.POUCHES end
  local out = {}
  for _, n in ipairs(M.POUCHES) do if limits.pouches[n] then out[#out + 1] = n end end
  return #out > 0 and out or M.POUCHES
end

--- Rows of a pouch whose name contains the filter (case-insensitive); id as "#id" when the name is unknown.
function M.filter_rows(rows, filter)
  local f = (filter or ""):lower()
  local out = {}
  for _, r in ipairs(rows or {}) do
    local label = (r.name and r.name ~= "") and r.name or ("#" .. tostring(r.item))
    if f == "" or label:lower():find(f, 1, true) then out[#out + 1] = r end
  end
  return out
end

local function limits_of(limits)
  local out = {}
  for k, v in pairs(M.DEFAULT_LIMITS) do out[k] = v end
  for k, v in pairs(limits or {}) do out[k] = v end
  return out
end
M.limits_of = limits_of

--- Whole non-negative number typed in a field: integer, or nil when it is not one.
function M.parse_int(s)
  if math.type(s) == "integer" then return s end
  if type(s) ~= "string" then return nil end
  local t = s:match("^%s*(%d+)%s*$")
  if not t or #t > 9 then return nil end
  return tonumber(t)
end

--- A form from a pokemon.core record (team() / box() entry).
function M.from_record(rec)
  local f = {
    species = rec.species, level = rec.level and tostring(rec.level) or "", nature = rec.nature or 0,
    shiny = rec.shiny == true, item = rec.held_item or 0, ivs = {}, evs = {}, moves = {},
  }
  for _, s in ipairs(M.STATS) do
    f.ivs[s] = tostring((rec.ivs or {})[s] or 0)
    f.evs[s] = tostring((rec.evs or {})[s] or 0)
  end
  for i = 1, M.MOVE_SLOTS do f.moves[i] = (rec.moves or {})[i] or 0 end
  return f
end

--- Sum of the EVs as typed (fields that are not numbers count as 0).
function M.ev_total(form)
  local n = 0
  for _, s in ipairs(M.STATS) do n = n + (M.parse_int(form.evs[s]) or 0) end
  return n
end

local function same_moves(a, b)
  if #a ~= #b then return false end
  for i = 1, #a do if a[i] ~= b[i] then return false end end
  return true
end

local function compact(moves)
  local out = {}
  for i = 1, M.MOVE_SLOTS do if (moves[i] or 0) ~= 0 then out[#out + 1] = moves[i] end end
  return out
end

--- Compares the form with the record it came from. Returns fields (only what changed, the table that
--- goes to encode_pokemon) and errors ({ key = message key }); errors is empty when the form is valid.
--- Error keys: field names `level`, `iv_<stat>`, `ev_<stat>`, `ev_total`, `moves`.
function M.to_fields(form, rec, limits)
  local L = limits_of(limits)
  local fields, errs = {}, {}
  local base = M.from_record(rec)

  if form.species ~= base.species then
    if math.type(form.species) ~= "integer" or form.species < 1 or form.species > L.species then
      errs.species = "err_species"
    else
      fields.species = form.species
    end
  end

  local level = M.parse_int(form.level)
  if form.level ~= base.level or (rec.level == nil and form.level ~= "") then
    if level == nil or level < 1 or level > L.level then errs.level = "err_level" else fields.level = level end
  end

  if form.nature ~= base.nature then fields.nature = form.nature end
  if form.shiny ~= base.shiny then fields.shiny = form.shiny end
  if form.item ~= base.item then
    if math.type(form.item) ~= "integer" or form.item < 0 or form.item > L.item then errs.item = "err_item"
    else fields.held_item = form.item end
  end

  for _, kind in ipairs({ "ivs", "evs" }) do
    local hi = kind == "ivs" and L.iv or L.ev
    for _, s in ipairs(M.STATS) do
      if form[kind][s] ~= base[kind][s] then
        local v = M.parse_int(form[kind][s])
        if v == nil or v > hi then
          errs[(kind == "ivs" and "iv_" or "ev_") .. s] = kind == "ivs" and "err_iv" or "err_ev"
        else
          fields[kind] = fields[kind] or {}
          fields[kind][s] = v
        end
      end
    end
  end
  if fields.evs and M.ev_total(form) > L.ev_total then errs.ev_total = "err_ev_total" end

  local moves = compact(form.moves)
  if not same_moves(moves, compact(base.moves)) then
    local seen = {}
    local bad
    for _, m in ipairs(moves) do
      if seen[m] or m < 1 or m > L.move then bad = true end
      seen[m] = true
    end
    if #moves == 0 or bad then errs.moves = "err_moves" else fields.moves = moves end
  end
  return fields, errs
end

--- True when `rec` (read back from the core) shows what `fields` asked for.
function M.matches(fields, rec)
  if fields.species and rec.species ~= fields.species then return false end
  if fields.level and rec.level ~= nil and rec.level ~= fields.level then return false end
  if fields.nature and rec.nature ~= fields.nature then return false end
  if fields.shiny ~= nil and rec.shiny ~= fields.shiny then return false end
  if fields.held_item and rec.held_item ~= fields.held_item then return false end
  for _, kind in ipairs({ "ivs", "evs" }) do
    for s, v in pairs(fields[kind] or {}) do
      if ((rec[kind] or {})[s]) ~= v then return false end
    end
  end
  if fields.moves and not same_moves(rec.moves or {}, fields.moves) then return false end
  return true
end

--- Short list of option entries { value, label } from a names list ({ {id, name}, ... }): the entries whose
--- name contains `filter` (case-insensitive), at most `max`, the entry `current` always included first.
function M.filter_options(list, filter, current, max, label_of)
  max = max or 100
  local f = (filter or ""):lower()
  local out, seen = {}, {}
  local function label(e) return e.name ~= "" and e.name or label_of(e.id) end
  if current ~= nil then
    local lbl = label_of(current)
    for _, e in ipairs(list or {}) do if e.id == current then lbl = label(e) break end end
    out[1] = { value = current, label = lbl }
    seen[current] = true
  end
  for _, e in ipairs(list or {}) do
    if #out >= max then break end
    if not seen[e.id] and (f == "" or label(e):lower():find(f, 1, true)) then
      out[#out + 1] = { value = e.id, label = label(e) }
      seen[e.id] = true
    end
  end
  return out
end

return M

end
__mod["ui.panel"] = function(...)
-- In-game panel tab "Editor", built for about 300 px. Pure builder: panel.build(ctx) -> block.
-- ctx = { tr, state, core, names, team, box, box_count, trainer }, see app.editor.
--   state.view = "list" | "edit"; state.tab = "team" | "box" | "bag"
-- Nothing is nested deeper than list -> one edit form.
local form_mod = require("model.form")

local M = {}

M.MAX_ROWS = 30

-- Table of the non-nil arguments (a nil in a table constructor would end ipairs early).
local function K(...)
  local out = {}
  for i = 1, select("#", ...) do
    local v = select(i, ...)
    if v then out[#out + 1] = v end
  end
  return out
end

local function label_of(id) return "#" .. tostring(id) end

local function mon_title(tr, rec)
  local name = (rec.nickname and rec.nickname ~= "") and rec.nickname or rec.species_name or label_of(rec.species)
  if rec.level then name = name .. " · " .. tr("level_short", { n = rec.level }) end
  return name
end

local function mon_sub(rec)
  if rec.nickname and rec.nickname ~= "" then return rec.species_name or label_of(rec.species) end
  return nil
end

local function banner(ctx)
  local m = ctx.state.msg
  if not m then return nil end
  return { type = "column", id = "msg", gap = 4, children = {
    { type = "badge", id = "msg-badge", text = ctx.tr("msg_" .. m.tone), tone = m.tone },
    { type = "text", id = "msg-text", text = m.text, style = "body", tone = m.tone },
    { type = "button", id = "msg-x", label = ctx.tr("dismiss"), action = "dismiss", variant = "quiet" },
  } }
end

local function gate(ctx)
  local core = ctx.core
  if core.state == "no_core" then
    return { type = "empty", id = "gate", title = ctx.tr("gate_core_title"), text = ctx.tr("gate_core_text"), tone = "danger" }
  elseif core.state == "unsupported" then
    return { type = "empty", id = "gate", title = ctx.tr("gate_game_title"), text = ctx.tr("gate_game_text") }
  elseif core.state == "no_write" then
    return { type = "empty", id = "gate", title = ctx.tr("gate_write_title"), text = ctx.tr("gate_write_text"), tone = "danger" }
  elseif core.state ~= "ready" then
    return { type = "empty", id = "gate", title = ctx.tr("gate_wait_title"), text = ctx.tr("gate_wait_text") }
  end
  return nil
end

local function team_rows(ctx, recs, action_value)
  local rows = {}
  for i, rec in ipairs(recs or {}) do
    if i > M.MAX_ROWS then break end
    rows[#rows + 1] = { id = "r" .. i, title = mon_title(ctx.tr, rec), sub = mon_sub(rec), action = "edit",
      value = action_value(rec) }
  end
  return rows
end

local function team_tab(ctx)
  local rows = team_rows(ctx, ctx.team, function(rec) return { kind = "team", slot = rec.slot } end)
  if #rows == 0 then
    return { type = "text", id = "list-empty", text = ctx.tr("team_empty"), style = "meta" }
  end
  return { type = "list", id = "list", rows = rows }
end

local function box_tab(ctx)
  local opts = {}
  for n = 1, math.min(ctx.box_count or 31, 100) do opts[#opts + 1] = { value = n, label = ctx.tr("box_n", { n = n }) } end
  local kids = { { type = "select", id = "box-select", options = opts, selected = ctx.state.box, action = "box_select" } }
  local rows = team_rows(ctx, ctx.box, function(rec) return { kind = "box", box = ctx.state.box, slot = rec.slot } end)
  if #rows == 0 then
    kids[#kids + 1] = { type = "text", id = "list-empty", text = ctx.tr("box_empty"), style = "meta" }
  else
    kids[#kids + 1] = { type = "list", id = "list", rows = rows }
  end
  return { type = "column", id = "box-col", gap = 8, children = kids }
end

local function filtered_select(ctx, id, list, current, filter, action, with_none)
  local opts = form_mod.filter_options(list, filter, current, with_none and 99 or 100, label_of)
  if with_none then
    local has_zero = false
    for _, o in ipairs(opts) do if o.value == 0 then has_zero = true end end
    if not has_zero then table.insert(opts, 1, { value = 0, label = ctx.tr("none") }) end
  end
  for _, o in ipairs(opts) do if o.value == 0 and with_none then o.label = ctx.tr("none") end end
  if #opts == 0 then opts[1] = { value = 0, label = ctx.tr("none") } end
  return { type = "select", id = id, options = opts, selected = current ~= nil and current or opts[1].value, action = action }
end

local function pouch_section(ctx)
  local st, tr = ctx.state, ctx.tr
  local limits = ctx.core.limits
  local chips = {}
  for _, name in ipairs(form_mod.pouches_of(limits)) do
    chips[#chips + 1] = { type = "chip", id = "pouch-" .. name, text = tr("pouch_" .. name), action = "pouch_" .. name,
      selected = st.pouch == name }
  end
  local kids = { { type = "grid", id = "pouch-chips", columns = 3, gap = 4, children = chips } }
  if type(ctx.bag) ~= "table" then
    local key = ctx.bag_err == "unsupported" and "bag_unsupported" or "bag_not_ready"
    kids[#kids + 1] = { type = "text", id = "bag-note", text = tr(key), style = "meta" }
    return { type = "section", id = "items-sec", title = tr("items_title"), children = kids }
  end
  local rows_all = ctx.bag[st.pouch] or {}
  local rows = {}
  local shown = form_mod.filter_rows(rows_all, st.bag_filter)
  for i, r in ipairs(shown) do
    if i > M.MAX_ROWS then break end
    rows[#rows + 1] = { id = "b" .. r.slot, title = (r.name and r.name ~= "") and r.name or label_of(r.item),
      sub = tr("item_count_sub", { n = r.count }), action = "bag_edit", value = { slot = r.slot } }
  end
  kids[#kids + 1] = { type = "textfield", id = "bag-filter", action = "bag_filter", text = st.bag_filter, live = true,
    placeholder = tr("filter_item") }
  if #rows == 0 then
    kids[#kids + 1] = { type = "text", id = "bag-empty", text = tr(#rows_all == 0 and "pouch_empty" or "pouch_no_match"), style = "meta" }
  else
    kids[#kids + 1] = { type = "list", id = "bag-list", rows = rows }
    if #shown > #rows then
      kids[#kids + 1] = { type = "text", id = "bag-more", text = tr("pouch_more", { n = #rows, total = #shown }), style = "meta" }
    end
  end
  local max = form_mod.pouch_max(limits, st.pouch)
  if st.sel and st.sel.pouch == st.pouch then
    local name
    for _, r in ipairs(rows_all) do if r.slot == st.sel.slot then name = r.name end end
    kids[#kids + 1] = { type = "section", id = "sel-sec", title = (name and name ~= "") and name or label_of(st.sel.item), children = {
      { type = "text", id = "count-l", text = tr("item_count_label", { max = max }), style = "meta" },
      { type = "textfield", id = "count-input", action = "count_input", text = st.count or "", live = true,
        error = st.count_err and tr(st.count_err, { max = max }) or nil },
      { type = "row", id = "sel-acts", gap = 8, align = "center", children = {
        { type = "button", id = "count-apply", label = tr("count_apply"), action = "count_apply", variant = "primary" },
        { type = "button", id = "item-remove", label = tr("item_remove"), action = "item_remove", variant = "danger" },
        { type = "button", id = "sel-close", label = tr("back"), action = "bag_close", variant = "quiet" },
      } },
    } }
  end
  local add = st.add
  local add_kids = {}
  if ctx.names.item then
    add_kids[#add_kids + 1] = { type = "textfield", id = "add-filter", action = "add_filter", text = add.filter, live = true,
      placeholder = tr("filter_item") }
    add_kids[#add_kids + 1] = filtered_select(ctx, "add-item", ctx.names.item, add.item, add.filter, "add_item", false)
  else
    add_kids[#add_kids + 1] = { type = "textfield", id = "add-id", action = "add_id", text = add.id, live = true,
      placeholder = tr("add_id_placeholder", { max = limits.item }), error = add.id_err and tr(add.id_err) or nil }
  end
  add_kids[#add_kids + 1] = { type = "textfield", id = "add-count", action = "add_count", text = add.count, live = true,
    placeholder = tr("add_count_placeholder", { max = max }), error = add.count_err and tr(add.count_err, { max = max }) or nil }
  add_kids[#add_kids + 1] = { type = "button", id = "add-apply", label = tr("add_apply"), action = "add_apply", variant = "primary" }
  kids[#kids + 1] = { type = "section", id = "add-sec", title = tr("add_title"), children = add_kids }
  return { type = "section", id = "items-sec", title = tr("items_title"), children = kids }
end

local function bag_tab(ctx)
  local st = ctx.state
  local limits = ctx.core.limits
  local kids = {
    { type = "section", id = "money-sec", title = ctx.tr("money_title"), children = {
      { type = "text", id = "money-now", style = "meta",
        text = ctx.trainer and ctx.trainer.money and ctx.tr("money_now", { n = ctx.trainer.money }) or ctx.tr("money_unknown") },
      { type = "textfield", id = "money-input", action = "money_input", text = st.money or "", live = true,
        placeholder = ctx.tr("money_placeholder", { max = limits.money }), error = st.money_err and ctx.tr(st.money_err) or nil },
      { type = "button", id = "money-apply", label = ctx.tr("money_apply"), action = "money_apply", variant = "primary" },
    } },
  }
  if ctx.bag_on then
    kids[#kids + 1] = pouch_section(ctx)
  else
    kids[#kids + 1] = { type = "section", id = "items-sec", title = ctx.tr("items_title"), children = {
      { type = "text", id = "items-note", text = ctx.tr("items_unsupported"), style = "meta" } } }
  end
  return { type = "column", id = "bag-col", gap = 12, children = kids }
end

local function list_view(ctx)
  local st = ctx.state
  local tabs = {
    { value = "team", label = ctx.tr("tab_team") }, { value = "box", label = ctx.tr("tab_box") },
    { value = "bag", label = ctx.tr("tab_bag") },
  }
  local content = st.tab == "box" and box_tab(ctx) or st.tab == "bag" and bag_tab(ctx) or team_tab(ctx)
  return { type = "column", id = "list-view", gap = 12, children = {
    { type = "segmented", id = "tabs", options = tabs, selected = st.tab, action = "tab" },
    content,
    { type = "text", id = "note", text = ctx.tr("note_backup"), style = "meta" },
  } }
end

-- ---- edit form ----

local function stat_grid(ctx, kind, form, errs)
  local st_names = { hp = "stat_hp", atk = "stat_atk", def = "stat_def", spe = "stat_spe", spa = "stat_spa", spd = "stat_spd" }
  local cells = {}
  for _, s in ipairs(form_mod.STATS) do
    local key = (kind == "ivs" and "iv_" or "ev_") .. s
    cells[#cells + 1] = { type = "column", id = key .. "-c", gap = 2, children = {
      { type = "text", id = key .. "-l", text = ctx.tr(st_names[s]), style = "meta" },
      { type = "textfield", id = key, action = key, text = form[kind][s], live = true, error = errs[key] and ctx.tr(errs[key]) or nil },
    } }
  end
  return { type = "grid", id = kind .. "-grid", columns = 3, gap = 8, children = cells }
end

local function edit_view(ctx)
  local st = ctx.state
  local tr = ctx.tr
  local f, errs, limits = st.form, st.errors or {}, ctx.core.limits
  local names = ctx.names
  local nature_opts = {}
  for n = 0, limits.nature do
    nature_opts[#nature_opts + 1] = { value = n, label = names.nature[n] or tr("nature_n", { n = n }) }
  end
  local total = form_mod.ev_total(f)
  local ev_tone = total > limits.ev_total and "danger" or "neutral"

  local moves = {}
  for i = 1, form_mod.MOVE_SLOTS do
    moves[#moves + 1] = filtered_select(ctx, "move" .. i, names.move, f.moves[i], st.filters.move, "move_" .. i, true)
  end

  local kids = {
    { type = "row", id = "e-head", gap = 8, align = "center", children = {
      { type = "button", id = "e-back", label = tr("back"), action = "back", variant = "quiet" },
      { type = "text", id = "e-title", text = mon_title(tr, st.rec), style = "heading" },
    } },
    { type = "section", id = "sec-basic", title = tr("sec_basic"), children = {
      { type = "textfield", id = "species-filter", action = "species_filter", text = st.filters.species, live = true,
        placeholder = tr("filter_species") },
      filtered_select(ctx, "species", names.species, f.species, st.filters.species, "species", false),
      { type = "text", id = "level-l", text = tr("level"), style = "meta" },
      { type = "textfield", id = "level", action = "level", text = f.level, live = true,
        error = errs.level and tr(errs.level) or nil },
      { type = "text", id = "nature-l", text = tr("nature"), style = "meta" },
      { type = "select", id = "nature", options = nature_opts, selected = f.nature, action = "nature" },
      { type = "toggle", id = "shiny", label = tr("shiny"), checked = f.shiny, action = "shiny" },
    } },
    { type = "section", id = "sec-moves", title = tr("sec_moves"), children = K(
      { type = "textfield", id = "move-filter", action = "move_filter", text = st.filters.move, live = true,
        placeholder = tr("filter_move") },
      { type = "column", id = "moves", gap = 4, children = moves },
      errs.moves and { type = "text", id = "moves-err", text = tr(errs.moves), style = "meta", tone = "danger" } or nil,
      { type = "text", id = "moves-note", text = tr("moves_note"), style = "meta" }
    ) },
    { type = "section", id = "sec-ivs", title = tr("sec_ivs"), children = { stat_grid(ctx, "ivs", f, errs) } },
    { type = "section", id = "sec-evs", title = tr("sec_evs"), children = K(
      stat_grid(ctx, "evs", f, errs),
      { type = "text", id = "ev-total", text = tr("ev_total", { n = total, max = limits.ev_total }), style = "meta", tone = ev_tone },
      errs.ev_total and { type = "text", id = "ev-err", text = tr(errs.ev_total), style = "meta", tone = "danger" } or nil
    ) },
    { type = "section", id = "sec-item", title = tr("sec_item"), children = {
      { type = "textfield", id = "item-filter", action = "item_filter", text = st.filters.item, live = true,
        placeholder = tr("filter_item") },
      filtered_select(ctx, "item", names.item, f.item, st.filters.item, "item", true),
    } },
  }
  local msg = banner(ctx)
  if msg then kids[#kids + 1] = msg end
  kids[#kids + 1] = { type = "row", id = "e-acts", gap = 8, align = "center", children = {
    { type = "button", id = "apply", label = tr("apply"), action = "apply", variant = "primary" },
    { type = "button", id = "reset", label = tr("reset"), action = "reset", variant = "quiet" },
  } }
  return { type = "column", id = "edit-view", gap = 12, children = kids }
end

function M.build(ctx)
  local g = gate(ctx)
  local kids = {}
  if g then
    kids[1] = g
  elseif ctx.state.view == "edit" and ctx.state.form then
    kids[1] = edit_view(ctx)
  else
    local msg = banner(ctx)
    if msg then kids[#kids + 1] = msg end
    kids[#kids + 1] = list_view(ctx)
  end
  return { type = "column", id = "panel", gap = 12, children = kids }
end

return M

end
require("main")
